begin;
do $$
declare d jsonb;
begin
  for d in select value from jsonb_array_elements($defs$[{"id":"7ad3d3db-fc97-5f17-8da3-88785f2be68c","key":"hh-session-clarity","version":"v1","instrumentLocale":"en","translationVersion":"hh-en-v1","timeframe":"right-now","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Session Clarity Pulse","source":{"title":"Holistic House — Session Clarity Pulse","status":"original-playful-non-diagnostic-reflection","reviewedAt":"2026-10-14"},"answerScale":{"min":0,"max":4},"responseAnchors":["Not at all","A little","Somewhat","Quite a lot","Very much"],"scoring":{"dimensions":[{"key":"state.session_clarity.overall","method":"mean","items":["hh-session-clarity.01","hh-session-clarity.02","hh-session-clarity.03","hh-session-clarity.04","hh-session-clarity.05","hh-session-clarity.06"],"min":0,"max":4,"dimensionClass":"state","sourceConstruct":"Session Clarity Pulse","direction":"higher-reported-resource"}]},"questions":[{"id":"hh-session-clarity.01","text":"During the most recent support conversation, I could bring up what mattered most to me.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.02","text":"I had space to say when something needed a clearer explanation.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.03","text":"I can name one idea I want to remember from that conversation.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.04","text":"I felt free to ask for a slower pace when I needed it.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.05","text":"I know one small step I might choose before my next conversation.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.06","text":"I know how to share feedback if that conversation did not feel helpful.","required":true,"direction":"higher-reported-resource"}],"optionalContext":[],"suggestedRepeatDays":7,"contentHash":"sha256:3f40f3b8d7626a0b3017cd40e2db4776d78eb7b690b3734f8117affb84ff2b1c"},{"id":"5a03a1de-3aa9-5998-8b1d-42ad234681df","key":"hh-session-clarity","version":"v1","instrumentLocale":"ru","translationVersion":"hh-ru-v1","timeframe":"right-now","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Ясность после консультации","source":{"title":"Holistic House — Session Clarity Pulse","status":"original-playful-non-diagnostic-reflection","reviewedAt":"2026-10-14"},"answerScale":{"min":0,"max":4},"responseAnchors":["Совсем нет","Немного","Отчасти","В значительной степени","Очень сильно"],"scoring":{"dimensions":[{"key":"state.session_clarity.overall","method":"mean","items":["hh-session-clarity.01","hh-session-clarity.02","hh-session-clarity.03","hh-session-clarity.04","hh-session-clarity.05","hh-session-clarity.06"],"min":0,"max":4,"dimensionClass":"state","sourceConstruct":"Ясность после консультации","direction":"higher-reported-resource"}]},"questions":[{"id":"hh-session-clarity.01","text":"Во время последнего разговора о поддержке я смог(ла) поднять самый важный для меня вопрос.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.02","text":"У меня была возможность сказать, когда требовалось более понятное объяснение.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.03","text":"Я могу назвать одну мысль, которую хочу сохранить после разговора.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.04","text":"Я чувствовал(а), что могу попросить замедлиться, когда это необходимо.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.05","text":"Я понимаю, какой небольшой шаг мог(ла) бы выбрать до следующего разговора.","required":true,"direction":"higher-reported-resource"},{"id":"hh-session-clarity.06","text":"Я знаю, как дать обратную связь, если разговор не показался полезным.","required":true,"direction":"higher-reported-resource"}],"optionalContext":[],"suggestedRepeatDays":7,"contentHash":"sha256:bcee3805d26b2d98838f26a2e54f1da94af6d7c0b8ca257d47d881bdf32b376a"}]$defs$::jsonb)
  loop
    if exists (select 1 from app.assessment_versions where id=(d->>'id')::uuid and content_hash<>d->>'contentHash') then
      raise exception 'Immutable assessment % differs from published definition', d->>'id';
    end if;
    insert into app.assessment_versions (
      id,definition_key,definition_version,instrument_locale,translation_version,
      definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
      timeframe,source_metadata,content_hash
    ) values (
      (d->>'id')::uuid,d->>'key',d->>'version',d->>'instrumentLocale',d->>'translationVersion',
      d,d->'questions',jsonb_build_object('type','integer','minimum',(d->'answerScale'->>'min')::int,'maximum',(d->'answerScale'->>'max')::int),
      d->>'scoringKey',d->>'scoringVersion',jsonb_build_object('version',d->>'resultVersion'),
      d->>'timeframe',d->'source',d->>'contentHash'
    ) on conflict (id) do nothing;
  end loop;
end $$;
commit;
